import numpy as np, time
from cache_baseline import LRUCache as BaseLRUCache
from collections import OrderedDict
class PyLRUCache:
    __slots__=('capacity','_cache')
    def __init__(self,capacity):
        self.capacity=capacity
        self._cache=OrderedDict()
    def get(self,key):
        try:
            val=self._cache.pop(key)
            self._cache[key]=val
            return val
        except KeyError:
            return -1
    def put(self,key,val):
        if key in self._cache:
            self._cache.pop(key)
            self._cache[key]=val
        else:
            if len(self._cache)>=self.capacity:
                self._cache.popitem(last=False)
            self._cache[key]=val
    def run_ops(self,buf):
        import numpy as np
        res=[]
        cap=self.capacity
        cache=self._cache
        pop=cache.pop
        setitem=cache.__setitem__
        for is_put,key,val in buf:
            if is_put:
                if key in cache:
                    pop(key)
                    setitem(key,val)
                else:
                    if len(cache)>=cap:
                        cache.popitem(last=False)
                    setitem(key,val)
            else:
                try:
                    v=pop(key)
                    setitem(key,v)
                except KeyError:
                    v=-1
                res.append(v)
        return np.array(res,dtype=np.int64)

def gen_ops(n,capacity,seed):
    rng=np.random.default_rng(seed)
    is_put=rng.random(n)<0.5
    ops=np.empty((n,3),dtype=np.int64)
    ops[:,0]=is_put
    ops[:,1]=rng.integers(0,capacity*3,n,endpoint=True)
    ops[:,2]=np.where(is_put,rng.integers(0,100_000,n,endpoint=True),0)
    return ops

n=2_000_000
capacity=10_000
seed=99
ops=gen_ops(n,capacity,seed)
start=time.perf_counter()
BaseLRUCache(capacity).run_ops(ops)
base_time=time.perf_counter()-start
print('baseline time',base_time)
start=time.perf_counter()
PyLRUCache(capacity).run_ops(ops)
py_time=time.perf_counter()-start
print('python time',py_time,'speedup',base_time/py_time)
